    """Calculate the sum of the squares of the digits of a number."""
    return sum(int(i)**2 for i in str(num))

def is_happy(num):
    """Check if a number is happy by finding a cycle of happy numbers."""
    seen = set()
    while num != 1 and num not in seen:
        seen.add(num)
        num = get_digits(num)
    return num == 1

