def is_happy_num(n):
    def get_next(n):
        total_sum = 0
        while n > 0:
            n, digit = divmod(n, 10)
            total_sum += digit ** 2
        return total_sum

    visited = set()
    while n != 1 and n not in visited:
        visited.add(n)
        n = get_next(n)

    return n == 1


