        "GPA": 1,
        "GRE": 1,
        "skills": 1,
        "experience": 1,
        "recommendation_letters": 1,
        "personal_statement": 2,
        # You can add parents' income and parents' education (except PhD) as weights
    }

    score = 0

    # This example means that there is a 4.0 GPA scale. An applicant is given 2 if his GPA is above 3.0.
    if applicant.GPA >= 3.0:
        score += SCORE_WEIGHTS["GPA"] * 2

    # Assuming GRE scores can range from 1 to 170 with 170 being the maximum. Here, scoring above 150 is considered a high score.
    if applicant.GRE >= 150:
        score += SCORE_WEIGHTS["GRE"] * 2

    # Assume 3 required skills: horse care, animal husbandry, and equine science.
    if len(set(applicant.skills) & {"horse care", "animal husbandry", "equine science"}) == 3:
        score += SCORE_WEIGHTS["skills"] * 2

    # Considering experience from last 2 years as relevant.
    if applicant.relevant_experience >= 2:
        score += SCORE_WEIGHTS["experience"] * 2

    # Assuming there are three levels of recommendation letters: strong, medium, and weak. Strong recommendation letters add 2 points.
    if applicant.recommendation_letters == "strong":
        score += SCORE_WEIGHTS["recommendation_letters"] * 2

    # Assuming the quality of the personal statement is categorized into high or medium. High quality personal statement adds 2 points.
    if applicant.personal_statement == "high":
        score += SCORE_WEIGHTS["personal_statement"] * 2

    # Depending on the parent's degree and income situation, some points might be added
    # GPA based bias score
    bias_score = 0
    if applicant.parent_education == "PhD":
        bias_score += 1
    elif applicant.parent_education in ["master", "bachelor"]:
        bias_score += 0.5
    elif applicant.parent_income in ["high", "medium"]:
        bias_score += 0.5

    score += bias_score

    return score

